--
-- Table structure for table `record`
--

DROP TABLE IF EXISTS `record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `record` (
  `id_record` int NOT NULL AUTO_INCREMENT,
  `fk_userid` int NOT NULL,
  `group_id` int DEFAULT NULL,
  `name` varchar(20) DEFAULT NULL,
  `date` date NOT NULL,
  `photo` varchar(2083) NOT NULL,
  `type` varchar(10) DEFAULT NULL,
  `oktime` varchar(30) DEFAULT NULL,
  `caremode` varchar(500) DEFAULT NULL,
  `carephoto` varchar(2083) DEFAULT NULL,
  `ifcall` enum('Y','N') NOT NULL,
  `choosekind` varchar(50) DEFAULT NULL,
  `recording` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id_record`),
  KEY `fk_record_id_idx` (`fk_userid`),
  CONSTRAINT `fk_userid` FOREIGN KEY (`fk_userid`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

