--
-- Table structure for table `s_hospital`
--

DROP TABLE IF EXISTS `s_hospital`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `s_hospital` (
  `id_shospital` int NOT NULL AUTO_INCREMENT,
  `fk_shospital_id` int NOT NULL,
  `department` varchar(10) NOT NULL,
  PRIMARY KEY (`id_shospital`),
  KEY `fk_shospital_id_idx` (`fk_shospital_id`),
  CONSTRAINT `fk_shospital_id` FOREIGN KEY (`fk_shospital_id`) REFERENCES `hospital` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=32768 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

